'use strict';
// Syllables are spoken beats, not individual letters or phonemes.
const wordPlaySyllables={napkin:['nap','kin'],basket:['bas','ket'],helmet:['hel','met'],mitten:['mit','ten']};
for(const word of ['pen','rug','napkin','basket','helmet','mitten'])if(!readingWords[word])readingWords[word]={word,tiles:[...word],picture:word,sounds:'Ask the grown-up to model the taught spellings.'};
const wordPlayGames=[
 {id:'picture-fishing',title:'The picture-fish pond',mode:'word-fishing',theme:'garden',items:['pig','dog','cap','bag'],units:['p','i','g','d','o','c','a','b'],why:'Read a whole short word, then catch the picture-fish carrying its meaning. Pictures check meaning after blending; they are not a substitute for reading the spellings.',adult:'Model the taught sounds, blend the whole word, then discuss the pictures. Compare d/p and g/p only if helpful. The fish carry picture badges; beds and animals are not really underwater.'},
 {id:'word-trolley',title:'The very useful delivery trolley',mode:'word-trolley',theme:'post',items:['cup|pan','hat|bag','pen|mop','map|cap'],units:['c','u','p','a','n','h','t','b','g','e','m','o'],why:'Read a two-item delivery list and load the matching picture cards in either order. The visible list reduces memory demands while print directs a practical action.',adult:'Read one word at a time. Keep the list visible; a child may point and an adult can load. These are picture cards, so every object fits the trolley.'},
 {id:'sticker-swap',title:'Robot’s mixed-up sticker album',mode:'word-stickers',theme:'workshop',items:['pig|dog|cap','cap|cup|bag','bed|pen|hat','map|mop|rug'],units:['p','i','g','d','o','c','a','u','b','e','n','h','t','m','r'],why:'Read movable labels and repair their picture matches. Swapping changes the album immediately, and labels remain editable until every match fits.',adult:'Name the pictures if needed, then read all spellings in each label together. With two labels a child may solve by elimination; a repaired album does not prove independent decoding.'},
 {id:'word-dominoes',title:'Domino trail to the little flag',mode:'word-dominoes',theme:'village',items:['cat|cap|cup','pig|pen|pan','dog|log|bag','bed|net|hat'],units:['c','a','t','p','u','i','g','e','n','d','o','l','b','h'],why:'Read the word at the end of a trail and connect a domino with the matching picture. Its next word changes the route, creating a three-link chain of print and meaning.',adult:'Read the exposed word before choosing its picture. Offer a model or a break between links. All choices remain still, with no countdown.'},
 {id:'syllable-carriages',title:'The two-beat word train',mode:'word-syllables',theme:'machine',items:['napkin','basket','helmet','mitten'],units:['n','a','p','k','i','b','s','e','t','h','l','m'],why:'Combine two syllable carriages, blend their printed word, then deliver it to a matching picture. Colour and underlines mark syllables, not separate sounds.',adult:'This is a supported next step after short words. Say and model each word and any untaught spellings first. nap|kin, bas|ket, hel|met and mit|ten each have two syllables. The two written t letters in mitten do not require two /t/ sounds. A syllable may contain several phonemes.'}
];
for(const game of wordPlayGames){game.extended=true;game.wordPlay=true;readingGames.push(game);}
const wordPlayCourses=[
 {id:'short-words-meanings',title:'Short words, real meanings',goal:'Blend short taught words and connect them with pictures through catching, packing and repairing labels.',need:'The child needs supported practice reading whole short words and understanding what they name.',activities:wordPlayGames.slice(0,3).map(g=>({engine:'reading',key:g.id})),home:'Write one familiar word on a card. Read it together and use its meaning to fetch a real object.'},
 {id:'word-paths-syllables',title:'Word paths & syllable pieces',goal:'Follow a short-word domino trail, then explore four supported two-syllable words.',need:'Short words are becoming manageable; the child is ready to link several word meanings or try a longer word with a model.',activities:wordPlayGames.slice(3).map(g=>({engine:'reading',key:g.id})),home:'Read a familiar short word in plain print. For a longer taught word, model its spoken syllables and blend it back together.'}
];
for(const course of wordPlayCourses){Object.assign(course,{reading:true,extended:true,level:'Adult-supported early reading',props:'A grown-up; taught English spellings; usual AAC, pointing or keyboard supports. No recorded voice, tracing, speed or independent speech required.',notice:['Which spellings need modelling','Whether pictures are understood separately from decoding','Which display, input and adult supports help']});readingCourses.push(course);readingSkill.courses.push(course);}
for(const section of parentSupportSections)if(['dyslexia','language','development','speech','motor','autism','attention'].includes(section.id))section.readingCourses=[...new Set([...(section.readingCourses||[]),...wordPlayCourses.map(c=>c.id)])];
